import { validar } from "./cupones.js";

export function total(lineas, cupon) {
  const bruto = lineas.reduce((suma, l) => suma + l.precio * l.cantidad, 0);
  return cupon && validar(cupon) ? Math.round(bruto * 0.9 * 100) / 100 : bruto;
}

